import ru.wildlik.wileyai.mobile.*;
import java.util.*;
import java.time.*;

public final class AndroidToolsProbe {
    static void check(boolean value){if(!value)throw new AssertionError();}
    static void rejected(Runnable action){try{action.run();throw new AssertionError("Invalid input accepted");}catch(IllegalArgumentException expected){}}
    public static void main(String[] args){String scenario=args[0];switch(scenario){
        case "strict-json"->{for(String text:List.of("{\"a\":1,\"a\":2}","{\"a\":1} trailing","[1,]","{\"a\":NaN}","{\"a\":01}","{\"a\":+1}","{\"a\":\"\\uD800\"}"))rejected(()->StrictJson.parse(text));check(StrictJson.parse("{\"a\":[true,null,123,\"Русский 😀\"]}") instanceof Map);}
        case "validate"->{check(AndroidTools.parse("{\"steps\":[{\"tool\":\"set_volume\",\"arguments\":{\"percent\":30}}],\"reply\":\"\"}").steps().size()==1);
            for(String payload:List.of("{\"percent\":101}","{\"percent\":-1}","{\"percent\":30.0}","{\"percent\":\"30\"}","{\"percent\":30,\"shell\":\"x\"}"))rejected(()->AndroidTools.validate("set_volume",(Map<?,?>)StrictJson.parse(payload)));
            rejected(()->AndroidTools.validate("shell",Map.of("command","id")));rejected(()->AndroidTools.validate("open_app",Map.of("app_name","  ")));rejected(()->AndroidTools.validate("open_app",Map.of("app_name","app\ncode")));
        }
        case "plan-limits"->{rejected(()->AndroidTools.parse("{\"steps\":[],\"execute\":true}"));String call="{\"tool\":\"get_time\",\"arguments\":{}}";rejected(()->AndroidTools.parse("{\"steps\":["+String.join(",",Collections.nCopies(5,call))+"]}"));}
        case "consent-cancel-expiry"->{var call=AndroidTools.validate("open_app",Map.of("app_name","Telegram"));var plan=new AndroidTools.Plan(List.of(call),"");ToolRun run=new ToolRun(plan);check(run.needsConfirmation());try{run.before(call,0);throw new AssertionError();}catch(IllegalStateException expected){}run.approve(100);run.cancel();try{run.before(call,101);throw new AssertionError();}catch(IllegalStateException expected){}ToolRun late=new ToolRun(plan);late.approve(0);try{late.before(call,45001);throw new AssertionError();}catch(IllegalStateException expected){}ToolRun once=new ToolRun(plan);once.approve(0);once.before(call,1);try{once.before(call,2);throw new AssertionError();}catch(IllegalStateException expected){}}
        case "reminder-time"->{var now=ZonedDateTime.parse("2026-10-30T23:00:00+05:00[Asia/Yekaterinburg]");var call=AndroidTools.validate("create_reminder",Map.of("text","Продукты","day","tomorrow","time","07:00"));check(AndroidTools.reminderTime(call,now)==now.toLocalDate().plusDays(1).atTime(7,0).atZone(now.getZone()).toInstant().toEpochMilli());rejected(()->AndroidTools.reminderTime(AndroidTools.validate("create_reminder",Map.of("text","x","day","today","time","07:00")),now));}
        case "retrieval-and-injection"->{check(!StructuredActionAdapter.shouldPlan("Сколько будет два плюс два?"));check(StructuredActionAdapter.shouldPlan("Будь добра, установи громкость 30 процентов"));check(StructuredActionAdapter.maxSteps("Будь добра, установи громкость 30 процентов")==1);check(StructuredActionAdapter.maxSteps("Открой Telegram и сделай громкость 30 процентов")==2);check(!StructuredActionAdapter.grammar(List.of(AndroidTools.get("set_volume")),1).contains("{0,3}"));check(StructuredActionAdapter.relevant("Установи для музыки 30 процентов громкости").stream().noneMatch(t->t.name().startsWith("media_")));check(StructuredActionAdapter.compound("Открой музыку, найди спокойный трек"));check(StructuredActionAdapter.compound("Открой Telegram и сделай громкость 30 процентов"));check(!StructuredActionAdapter.compound("Открой Telegram"));check(StructuredActionAdapter.relevant("Открой Telegram и сделай громкость 30 процентов").stream().anyMatch(t->t.name().equals("open_app")));for(String request:List.of("Объясни фразу: открой Telegram","Например, открой Telegram","Не открывай Telegram","\"Открой Telegram\""))check(!StructuredActionAdapter.actionIntent(request));check(StructuredActionAdapter.actionIntent("Будь добра, поставь будильник на 7 утра"));var allowed=List.of(AndroidTools.get("get_time"));rejected(()->StructuredActionAdapter.parse("{\"steps\":[{\"tool\":\"open_app\",\"arguments\":{\"app_name\":\"Telegram\"}}]}",allowed));}
        default->throw new AssertionError("unknown scenario");}
        System.out.println("ANDROID_TOOLS_OK "+scenario);
    }
}
